interface TitlesProps {
  title: string;
  align?: "left" | "center" | "right";
  children?: React.ReactNode;
}

/**
 * @description Atom: Titles.
 * Displays a styled title with diagonal accents and horizontal lines using theme CSS variables.
 * @param {TitlesProps} props - Component properties.
 */
export default function Titles({
  title,
  align = "left",
  children,
}: TitlesProps) {
  const textNode = (
    <div className="flex items-center border-b-[3px] border-[var(--wb-primary)] px-3 shrink-0">
      <h1 className="text-[var(--wb-on-surface)] font-bold text-2xl md:text-3xl whitespace-nowrap leading-none pb-1">
        {title}
      </h1>
    </div>
  );

  const diagonalUp = (
    <div className="w-6 shrink-0 relative overflow-visible">
      <svg
        className="absolute inset-0 w-full h-full overflow-visible"
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
      >
        <line
          x1="0"
          y1="100"
          x2="100"
          y2="0"
          stroke="var(--wb-primary)"
          strokeWidth="3"
          vectorEffect="non-scaling-stroke"
        />
      </svg>
    </div>
  );

  const diagonalDown = (
    <div className="w-6 shrink-0 relative overflow-visible">
      <svg
        className="absolute inset-0 w-full h-full overflow-visible"
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
      >
        <line
          x1="0"
          y1="0"
          x2="100"
          y2="100"
          stroke="var(--wb-primary)"
          strokeWidth="3"
          vectorEffect="non-scaling-stroke"
        />
      </svg>
    </div>
  );

  const lineTop = (
    <div className="flex-1 border-t-[3px] border-[var(--wb-primary)] min-w-[20px] pt-3 pr-2 flex justify-end">
      {children}
    </div>
  );

  return (
    <div className="flex items-stretch -mx-8 px-0 sm:mx-0 sm:px-6 my-6">
      {align === "left" && (
        <>
          {textNode}
          {diagonalUp}
          {lineTop}
        </>
      )}

      {align === "right" && (
        <>
          {lineTop}
          {diagonalDown}
          {textNode}
        </>
      )}

      {align === "center" && (
        <>
          {lineTop}
          {diagonalDown}
          {textNode}
          {diagonalUp}
          {lineTop}
        </>
      )}
    </div>
  );
}
