import http from "@http";
import { FNF_GAME_ID, ENGINE_CATEGORIES } from "../constants";
import { isExcluded } from "../utils";

/**
 * In-memory cache to store the pagination state and records for the "Ripe" algorithm.
 * Keeps track of which page to fetch next and prevents duplicates.
 */
const ripeCache = new Map<
  string,
  {
    records: any[];
    sourcePage: number;
    modIds: Set<number>;
    isComplete: boolean;
  }
>();

/**
 * Fetches "Ripe" (Most Liked historically) records by querying all allowed categories in parallel.
 * Results are merged and sorted locally to provide a fallback infinite scroll when Discovery runs out.
 * 
 * @param {string[] | null} targetEngineIds - Optional array of engine IDs to filter by. Defaults to `null` (all engines).
 * @param {number} maxPages - Maximum depth of pages to query per execution to avoid hanging.
 * @param {number} maxRecords - Number of valid records needed before returning.
 * @returns {Promise<any[]>} An array of historical top mods.
 */
export async function fetchRipeRecords(
  targetEngineIds: string[] | null = null,
  maxPages = 4,
  maxRecords = 30,
) {
  const isAll =
    !targetEngineIds ||
    targetEngineIds.length === 0 ||
    (targetEngineIds.length === 1 && targetEngineIds[0] === "all");
  const cacheKey = isAll ? "all" : targetEngineIds!.slice().sort().join(",");

  if (!ripeCache.has(cacheKey)) {
    ripeCache.set(cacheKey, {
      records: [],
      sourcePage: 1,
      modIds: new Set(),
      isComplete: false,
    });
  }

  const state = ripeCache.get(cacheKey)!;

  if (state.records.length >= maxRecords || state.isComplete) {
    return state.records.slice(0, maxRecords);
  }

  const indexUrl = "https://gamebanana.com/apiv11/Mod/Index";

  let categoryIds = Object.keys(ENGINE_CATEGORIES).map(Number);
  if (!isAll) {
    categoryIds = targetEngineIds!
      .map((id) => {
        const match = Object.entries(ENGINE_CATEGORIES).find(
          ([_, cat]) => cat.id === id,
        );
        return match ? Number(match[0]) : -1;
      })
      .filter((id) => id !== -1);
  }

  while (
    !state.isComplete &&
    state.records.length < maxRecords &&
    state.sourcePage <= maxPages
  ) {
    try {
      let allFetched: any[] = [];

      let hasNetworkError = false;

      if (isAll) {
        const perPageToFetch = Math.max(15, Math.min(30, maxRecords));
        const url = `${indexUrl}?_aFilters[Generic_Game]=${FNF_GAME_ID}&_sSort=Generic_MostLiked&_nPerpage=${perPageToFetch}&_nPage=${state.sourcePage}`;
        try {
          const res: any = await http.fetchJson(url);
          allFetched = res?._aRecords || [];
        } catch (err) {
          console.warn("fetchRipeRecords failed for all engines:", err);
          hasNetworkError = true;
          allFetched = [];
        }
      } else {
        const perCatPerPage = Math.max(10, Math.ceil(maxRecords / categoryIds.length));
        const requests = categoryIds.map(async (catId) => {
          const url = `${indexUrl}?_aFilters[Generic_Game]=${FNF_GAME_ID}&_aFilters[Generic_Category]=${catId}&_sSort=Generic_MostLiked&_nPerpage=${perCatPerPage}&_nPage=${state.sourcePage}`;
          try {
            const res: any = await http.fetchJson(url);
            const records = res?._aRecords || [];
            return records.map((r: any) => ({
              ...r,
              __resolvedEngineId: ENGINE_CATEGORIES[catId]?.id,
            }));
          } catch (err) {
            hasNetworkError = true;
            return [];
          }
        });

        const results = await Promise.all(requests);
        allFetched = results.flat();
      }

      if (hasNetworkError && allFetched.length === 0) {
        if (state.records.length === 0) {
          ripeCache.delete(cacheKey);
          throw new Error("Failed to fetch ripe mods from GameBanana (network error or timeout)");
        }
        break;
      }

      if (allFetched.length === 0) {
        state.isComplete = true;
        break;
      }

      allFetched.sort((a, b) => (b._nLikeCount || 0) - (a._nLikeCount || 0));

      for (const mod of allFetched) {
        if (
          mod?._bIsTrashed ||
          mod?._bIsDeleted ||
          mod?._sInitialVisibility === "hide" ||
          isExcluded(mod)
        ) {
          continue;
        }

        if (state.modIds.has(mod._idRow)) continue;

        state.modIds.add(mod._idRow);
        state.records.push(mod);
      }
      state.sourcePage++;
    } catch (error) {
      break;
    }
  }

  return state.records.slice(0, maxRecords);
}

export function clearRipeCache() {
  ripeCache.clear();
}

